mapper.select:
SELECT u.user_id,u.dept_id,u.status AS user_status,u.del_flag,p.profile_id,p.legal_entity_id,
p.work_location,p.work_start_date,p.entry_date,p.employee_status,p.update_time AS profile_updated_at
FROM sys_user u LEFT JOIN sys_user_profile p ON p.user_id=u.user_id WHERE u.user_id=#{userId}

SELECT u.user_id FROM sys_user u JOIN sys_user_profile p ON p.user_id=u.user_id
WHERE u.user_id > #{afterId} AND u.status='0' AND u.del_flag='0'
ORDER BY u.user_id LIMIT #{limit}
